"use client";
import { useLocale, useTranslations } from "next-intl";
import { useCallback } from "react";
import type { Locale } from "@/i18n/messages";
export function useLanguage() {
  const locale = useLocale() as Locale;
  const common = useTranslations("common");
  const l = useCallback(
    (en: string, es: string) => (locale === "es" ? es : en),
    [locale],
  );
  const number = useCallback(
    (value: number, options?: Intl.NumberFormatOptions) =>
      new Intl.NumberFormat(
        locale === "es" ? "es-CO" : "en-US",
        options,
      ).format(value),
    [locale],
  );
  const currency = useCallback(
    (value: number) =>
      number(value, {
        style: "currency",
        currency: "USD",
        maximumFractionDigits: 0,
      }),
    [number],
  );
  const date = useCallback(
    (value: Date | string, options?: Intl.DateTimeFormatOptions) =>
      new Intl.DateTimeFormat(
        locale === "es" ? "es-CO" : "en-US",
        options ?? { month: "short", day: "numeric", year: "numeric" },
      ).format(
        new Date(
          typeof value === "string" && value.length === 10
            ? `${value}T12:00:00`
            : value,
        ),
      ),
    [locale],
  );
  return { locale, common, l, number, currency, date };
}

export type Theme = "light" | "dark";
export type PaletteId = "aurora" | "violet" | "ocean" | "mint" | "ember" | "rose";
export type Material = "flat" | "elevated" | "glass" | "gradient";
export type MotionLevel = "off" | "gentle" | "expressive";
export type HoverEffect = "none" | "lift" | "glow" | "spotlight" | "tilt" | "magnetic";
export type GradientKind = "linear" | "radial" | "mesh";
export type ShaderKind = "aurora" | "waves" | "iridescent" | "none";
export interface AppearanceConfig {
  version: 1;
  theme: Theme;
  palette: PaletteId;
  colors: { primary: string; secondary: string; tertiary: string };
  material: Material;
  radius: number;
  density: "comfortable" | "compact";
  typography: "modern" | "editorial";
  motion: MotionLevel;
  hover: HoverEffect;
  shadow: number;
  border: number;
  gradient: {
    kind: GradientKind;
    angle: number;
    intensity: number;
    stops: { color: string; position: number }[];
  };
  shader: {
    kind: ShaderKind;
    speed: number;
    scale: number;
    intensity: number;
    paused: boolean;
  };
}
export interface SavedAppearance {
  id: string;
  name: string;
  config: AppearanceConfig;
}
export const appearanceStorageKey = "aureform:appearance:v1";
export const presetsStorageKey = "aureform:presets:v1";
