  if (readable(stops)) return stops;
  const endpoint = text > .5 ? "#000000" : "#FFFFFF";
  let low = 0, high = 1;
  for (let step = 0; step < 14; step++) {
    const amount = (low + high) / 2;
    if (readable(stops.map((color) => mixColor(color, endpoint, amount)))) high = amount;
