    step: z.number().int().min(0).max(3),
    organizationName: z.string().max(100),
    workspaceName: z.string().max(100),
    workspaceSlug: z.string().max(64),
    invites: z
      .array(z.object({ email: z.string().max(254), role: inviteRoleSchema }))
      .max(50),
    completed: z.boolean(),
    workspaceId: z.string().optional(),
  }),
});

/** Untrusted browser persistence is checked before it reaches any UI. */
export function parseSaasState(value: unknown): SaasDemoState | null {
  const parsed = stateSchema.safeParse(value);
  if (!parsed.success) return null;
  const state = parsed.data as SaasDemoState;
  const ids = state.workspaces.map((item) => item.id);
  if (
    new Set(ids).size !== ids.length ||
    !ids.includes(state.activeWorkspaceId)
  )
    return null;
  const slugs = state.workspaces.map((item) => item.slug);
  if (new Set(slugs).size !== slugs.length) return null;
  for (const id of ids) {
    if (!Object.hasOwn(state.data, id)) return null;
    const data = state.data[id];
    if (
      data.members.filter((member) => member.role === "owner").length !== 1 ||
      !data.members.some(
        (member) => member.role === "owner" && member.status === "active",
      )
    )
      return null;
    if (
      !data.members.some(
        (member) =>
          member.id === state.currentMemberId && member.status === "active",
      )
    )
      return null;
    if (
      new Set(data.customers.map((item) => item.id)).size !==
      data.customers.length
    )
      return null;
    if (
      new Set(data.members.map((item) => item.id)).size !== data.members.length
    )
      return null;
    if (
      new Set(data.members.map((item) => item.email.toLowerCase())).size !==
      data.members.length
    )
      return null;
  }
  return state;
}

export function updateWorkspaceData(
  state: SaasDemoState,
  id: string,
  updater: (previous: WorkspaceData) => WorkspaceData,
): SaasDemoState {
  if (!Object.hasOwn(state.data, id)) throw new SaasError("missing");
  return { ...state, data: { ...state.data, [id]: updater(state.data[id]) } };
}
export function transferWorkspaceOwnership(
  members: WorkspaceMember[],
  actorId: string,
  targetId: string,
): WorkspaceMember[] {
  const actor = members.find((item) => item.id === actorId);
  const target = members.find((item) => item.id === targetId);
  if (actor?.role !== "owner" || actor.status !== "active")
    throw new SaasError("permission");
  if (!target || target.status !== "active" || actorId === targetId)
    throw new SaasError("invalid");
  return members.map((item) =>
    item.id === actorId
      ? { ...item, role: "admin" }
      : item.id === targetId
        ? { ...item, role: "owner" }
        : item,
  );
}
export function changeWorkspaceMemberRole(
  members: WorkspaceMember[],
  targetId: string,
  role: WorkspaceRole,
  actorId?: string,
): WorkspaceMember[] {
  const target = members.find((item) => item.id === targetId);
  if (!target) throw new SaasError("missing");
  if (target.role === "owner" || role === "owner" || targetId === actorId)
    throw new SaasError("owner");
  return members.map((item) =>
    item.id === targetId ? { ...item, role } : item,
  );
}
export function removeWorkspaceMember(
  members: WorkspaceMember[],
  actorId: string,
  targetId: string,
): WorkspaceMember[] {
  const target = members.find((item) => item.id === targetId);
  if (!target) throw new SaasError("missing");
  if (target.role === "owner" || targetId === actorId)
    throw new SaasError("owner");
  return members.filter((item) => item.id !== targetId);
}

export type CustomerImportResult = {
  created: number;
  updated: number;
  skipped: number;
  failed: number;
};
/** Transactional merge; callers commit the result only after cancellation checks. */
export function mergeImportedCustomers(
  existing: Customer[],
  imported: Customer[],
  mode: "skip" | "update",
): { customers: Customer[]; result: CustomerImportResult } {
  const customers = existing.map((item) => ({ ...item }));
  const indices = new Map(
    customers.map((item, index) => [item.email.trim().toLowerCase(), index]),
  );
  const result: CustomerImportResult = {
    created: 0,
    updated: 0,
    skipped: 0,
    failed: 0,
  };
  for (const candidate of imported) {
    const parsed = customerSchema.safeParse(candidate);
    if (!parsed.success) {
      result.failed++;
      continue;
    }
    const customer = parsed.data;
    const email = customer.email.trim().toLowerCase();
    const index = indices.get(email);
    if (index !== undefined) {
      if (mode === "skip") {
        result.skipped++;
      } else {
        customers[index] = { ...customer, id: customers[index].id };
        result.updated++;
      }
    } else {
      if (customers.some((item) => item.id === customer.id)) {
        result.failed++;
        continue;
      }
      indices.set(email, customers.length);
      customers.push(customer);
      result.created++;
    }
  }
  return { customers, result };
}

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}
export function downloadText(
  filename: string,
  text: string,
  type = "text/plain",
) {
  const url = URL.createObjectURL(new Blob([text], { type }));
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  a.click();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}
export function csv(rows: Record<string, unknown>[]) {
  if (!rows.length) return "";
  const keys = Object.keys(rows[0]);
  const escape = (value: unknown) => {
    const raw = String(value ?? "");
    const safe = /^[=+@\t\r-]/.test(raw) ? `'${raw}` : raw;
    return `"${safe.replaceAll('"', '""')}"`;
  };
  return [
    keys.map(escape).join(","),
    ...rows.map((row) => keys.map((k) => escape(row[k])).join(",")),
  ].join("\r\n");
}

/*
 * Aureform effects. Import after the generated tokens.css in globals.css.
 * Component-layer rules allow Tailwind utilities to override decoration.
 * Shadow composition retains Tailwind 4 focus rings.
 */
@layer components {
  .af-surface-gradient {
    background-color: var(--surface);
    background-image: var(--af-gradient-surface);
  }

  .af-hero-gradient {
    background-color: var(--background);
    background-image: var(--af-gradient-hero);
  }

  .af-shadow-soft {
    --tw-shadow: var(--af-shadow-soft);
  }

  .af-shadow-elevated {
    --tw-shadow: var(--af-hover-shadow, var(--af-shadow-elevated));
  }

  .af-shadow-floating {
    --tw-shadow: var(--af-shadow-floating);
  }

  .af-shadow-soft,
  .af-shadow-elevated,
  .af-shadow-floating,
  .af-hover-card,
  .af-button {
    box-shadow:
      var(--tw-inset-shadow, 0 0 #0000), var(--tw-inset-ring-shadow, 0 0 #0000),
      var(--tw-ring-offset-shadow, 0 0 #0000), var(--tw-ring-shadow, 0 0 #0000),
      var(--tw-shadow, 0 0 #0000);
  }

  .af-button {
    transition:
      background-color var(--af-motion-fast) var(--af-motion-easing),
      border-color var(--af-motion-fast) var(--af-motion-easing),
      color var(--af-motion-fast) var(--af-motion-easing),
      box-shadow var(--af-motion-hover) var(--af-motion-easing);
  }

  .af-button-primary,
  .af-button-outline,
  .af-button-surface,
  .af-button-destructive {
    background-image: var(--af-gradient-control);
  }

  .af-button-primary,
  .af-button-surface,
  .af-button-destructive {
    --tw-shadow: var(--af-shadow-soft);
  }

  .af-hover-card {
    transition:
      background-color var(--af-motion-fast) var(--af-motion-easing),
      border-color var(--af-motion-fast) var(--af-motion-easing),
      box-shadow var(--af-motion-hover) var(--af-motion-easing),
      transform var(--af-motion-hover) var(--af-motion-easing);
  }

  .af-hover-link {
    color: var(--primary);
    text-decoration-line: underline;
    text-decoration-color: color-mix(in srgb, var(--primary) 45%, transparent);
    text-decoration-thickness: 1px;
    text-underline-offset: 0.22em;
    transition:
      color var(--af-motion-fast) var(--af-motion-easing),
      text-decoration-color var(--af-motion-fast) var(--af-motion-easing);
  }

  .af-hover-link:where(
      :not(
        :disabled,
        [data-disabled],
        [aria-disabled="true"],
        [aria-busy="true"]
      )
    ):focus-visible {
    color: var(--primary-hover);
    text-decoration-color: currentColor;
    text-decoration-thickness: 2px;
    outline: 2px solid var(--ring);
    outline-offset: 3px;
  }

  @media (hover: hover) and (pointer: fine) {
    .af-button-outline:where(
        :not(
          :disabled,
          [data-disabled],
          [aria-disabled="true"],
          [aria-busy="true"]
        )
      ):hover {
      --tw-shadow: var(--af-shadow-soft);
    }

    .af-hover-link:where(
        :not(
          :disabled,
          [data-disabled],
          [aria-disabled="true"],
          [aria-busy="true"]
        )
      ):hover {
      color: var(--primary-hover);
      text-decoration-color: currentColor;
      text-decoration-thickness: 2px;
    }
  }

  .af-button:where(
      :not(
        :disabled,
        [data-disabled],
        [aria-disabled="true"],
        [aria-busy="true"]
      )
    ):active {
    --tw-shadow: 0 0 #0000;
  }

  .af-button:where(
    :disabled,
    [data-disabled],
    [aria-disabled="true"],
    [aria-busy="true"]
  ),
  .af-hover-card:where(
    :disabled,
    [data-disabled],
    [aria-disabled="true"],
    [aria-busy="true"]
  ),
  .af-hover-link:where(
    :disabled,
    [data-disabled],
    [aria-disabled="true"],
    [aria-busy="true"]
  ) {
    cursor: default;
    pointer-events: none;
    animation: none;
    transition: none;
    transform: none;
    translate: none;
  }

  .af-button:where(
    :disabled,
    [data-disabled],
    [aria-disabled="true"],
    [aria-busy="true"]
  ) {
    --tw-shadow: 0 0 #0000;
    background-image: none;
  }
}

/* Interactive state colors must take precedence over a base bg-surface utility. */
@layer utilities {
  .af-hover-card:where(
      :not(
        :disabled,
        [data-disabled],
        [aria-disabled="true"],
        [aria-busy="true"]
      )
    ):focus-visible {
    --tw-shadow: var(--af-shadow-elevated);
    background-color: var(--af-shade-card);
    outline: 2px solid var(--ring);
    outline-offset: 3px;
    transform: translateY(var(--af-motion-lift));
  }

  @media (hover: hover) and (pointer: fine) {
    .af-hover-card:where(
        :not(
          :disabled,
          [data-disabled],
          [aria-disabled="true"],
          [aria-busy="true"]
        )
      ):hover {
      --tw-shadow: var(--af-hover-shadow, var(--af-shadow-elevated));
      background-color: var(--af-shade-card);
      transform: translateY(var(--af-motion-lift));
    }
  }
}

@layer components {
  .af-appearance-scope {
    color: var(--foreground);
    background-color: var(--background);
    font-family: var(--font-manrope, "Manrope"), system-ui, sans-serif;
  }

  .af-gradient-text {
    color: var(--primary);
    background-image: var(--af-gradient-text);
